-- Records of evaluations
-- ----------------------------
INSERT INTO `evaluations` VALUES (2, 1, 62, NULL, 'HEALTH-NEWS', 1, '早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，', '2025-07-27 20:45:53');
INSERT INTO `evaluations` VALUES (5, NULL, 62, NULL, 'HEALTH-NEWS', 2, '鸡肉：锅中倒油烧至六成热（筷子插入有', '2025-08-03 16:36:40');
INSERT INTO `evaluations` VALUES (6, 5, 62, NULL, 'HEALTH-NEWS', 2, '6456546', '2025-08-03 16:36:46');
INSERT INTO `evaluations` VALUES (7, NULL, 62, NULL, 'HEALTH-NEWS', 2, '倒油烧至六成热（筷子插入有细小气泡），放入鸡块炸至表面微黄后捞出；待油温升至八成热，复炸 1 分钟至金黄酥脆，捞出控油备用', '2025-08-04 13:44:28');
INSERT INTO `evaluations` VALUES (9, NULL, 63, NULL, 'HEALTH-NEWS', 6, '：锅中留少许底油，放入姜片、蒜末、葱段爆香，加入花椒和干辣椒段炒出辣味（注意小火避免炒糊），可加 1 勺豆瓣酱增加风味。\n翻炒入味：倒入炸好的鸡块，大火快速翻炒 2 分钟，让辣椒和花椒的香味裹满鸡肉，加少许生抽调味，最后撒上白芝麻和葱花翻炒均匀', '2025-08-05 16:36:17');
INSERT INTO `evaluations` VALUES (10, NULL, 62, NULL, 'HEALTH-NEWS', 7, ' + 水果能快速补充维生素。早餐加入菠菜、', '2025-08-05 18:03:51');
INSERT INTO `evaluations` VALUES (13, 12, 61, NULL, 'HEALTH-NEWS', 7, '或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。', '2025-08-05 19:51:16');
INSERT INTO `evaluations` VALUES (14, NULL, 62, NULL, 'HEALTH-NEWS', 7, '**aaaaa', '2025-08-05 20:06:09');
INSERT INTO `evaluations` VALUES (15, NULL, 61, NULL, 'HEALTH-NEWS', 14, 'NIHAO ', '2026-03-27 22:52:00');
