-- ----------------------------
-- Table structure for flow_index
-- ----------------------------
DROP TABLE IF EXISTS `flow_index`;
CREATE TABLE `flow_index`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '流量指标表主键ID，自增',
  `type` int NULL DEFAULT NULL COMMENT '流量类型（1：展现；2：浏览；3：点赞；4：收藏；5：停留）',
  `content_module` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '内容模块',
  `content_id` int NULL DEFAULT NULL COMMENT '内容ID，外键',
  `times` bigint NULL DEFAULT NULL COMMENT '停留时长（只有当流量类型是停留时，才需要设置这个字段）',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3851 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '流量指标表' ROW_FORMAT = DYNAMIC;

