-- ----------------------------
-- Table structure for health_model
-- ----------------------------
DROP TABLE IF EXISTS `health_model`;
CREATE TABLE `health_model`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '健康模型表主键ID，自增',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '模型名',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '模型简介',
  `icon_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标',
  `unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '单位',
  `symbol` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '符号',
  `normal_value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '正常值范围，以英文逗号“,”进行分割',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `is_global` tinyint(1) NULL DEFAULT NULL COMMENT '是否是全局模型',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '健康模型表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of health_model
-- ----------------------------
INSERT INTO `health_model` VALUES (2, '心率', '心率是指心脏每分钟跳动的次数，是反映心血管功能的重要指标。正常成年人静息状态下心率一般在 60-100 次 / 分钟，运动员或长期锻炼者可能偏低，属于正常现象', '/api/v1.0/self-health-api/file/getFile?fileName=1753597325751rate.png', '次 / 分钟', 'HR', '60,100', 1, 0, '2025-07-27 14:22:07');
INSERT INTO `health_model` VALUES (4, '体重', '体重是反映人体骨骼、肌肉、脂肪等组织总量的指标，受年龄、性别、身高等因素影响。保持健康体重可降低糖尿病、心血管疾病等患病风险，建议定期监测并结合体脂率综合评估。', '/api/v1.0/self-health-api/file/getFile?fileName=1753670454370weight.png', '千克（kg）', 'BW', '50,90', 62, 1, '2025-07-28 10:41:42');
INSERT INTO `health_model` VALUES (5, '睡眠时长', '睡眠时长指全天累计睡眠的时间，成年人正常范围为 7-9 小时。充足的睡眠有助于恢复体力、巩固记忆、调节情绪，长期睡眠不足可能导致免疫力下降、注意力不集中等问题。', '/api/v1.0/self-health-api/file/getFile?fileName=1753670667959s1.png', '小时（h）', 'ST', '7,9', 62, 1, '2025-07-28 10:44:44');
INSERT INTO `health_model` VALUES (6, '身体质量指数（BMI）', 'BMI 是评估人体胖瘦程度和健康风险的指标，偏瘦：BMI ＜ 18.5，正常：18.5 ≤ BMI ≤ 23.9，超重：24.0 ≤ BMI ≤ 27.9，肥胖：BMI ≥ 28.0', '/api/v1.0/self-health-api/file/getFile?fileName=1753760115590BMI.png', '(该模型暂无数值单位)', 'BMI', '18.5,23.9', 1, 0, '2025-07-29 11:36:06');
INSERT INTO `health_model` VALUES (9, '血压【低压】', '血液在血管内流动时对血管壁的压力，分收缩压和舒张压', '/api/v1.0/self-health-api/file/getFile?fileName=1754393475022press.png', '毫米汞柱', 'BP', '60,90', NULL, 0, '2025-08-05 19:32:33');
INSERT INTO `health_model` VALUES (10, '血压【高压】', '血液在血管内流动时对血管壁的压力，分收缩压和舒张压', '/api/v1.0/self-health-api/file/getFile?fileName=1754393568189press.png', '毫米汞柱', 'BP', '90,140', NULL, 0, '2025-08-05 19:33:15');
INSERT INTO `health_model` VALUES (11, '血糖', '血液中的葡萄糖浓度，反映人体糖代谢水平', '/api/v1.0/self-health-api/file/getFile?fileName=1754393779064xt.png', '毫摩尔 / 升', 'BG', '3.9,6.1', NULL, 0, '2025-08-05 19:36:52');
INSERT INTO `health_model` VALUES (12, '血氧饱和度', '血液中氧气结合血红蛋白占总血红蛋白的百分比', '/api/v1.0/self-health-api/file/getFile?fileName=1754393859179xy.png', '%', 'SpO₂', '95,100', NULL, 0, '2025-08-05 19:38:04');
INSERT INTO `health_model` VALUES (13, '体脂率', '身体脂肪重量占总体重的百分比，评估肥胖程度的重要指标', '/api/v1.0/self-health-api/file/getFile?fileName=1754393935430xy.png', '%', 'BF%', '18,25', NULL, 0, '2025-08-05 19:39:11');
INSERT INTO `health_model` VALUES (14, '午休时长', '午休时长，最佳睡眠时长半小时左右', '/api/v1.0/self-health-api/file/getFile?fileName=1754394071265s1.png', '小时（h）', 'ST', '0.5,0.6', 1, 0, '2025-08-05 19:40:56');
INSERT INTO `health_model` VALUES (15, '步数', '每日行走步数是衡量日常活动量的基础指标，建议成年人每日目标8000-10000步，有助于维持心肺功能和控制体重', '/api/v1.0/self-health-api/file/getFile?fileName=1753670454370weight.png', '步', 'STEPS', '8000,10000', NULL, 0, '2025-09-01 10:00:00');
INSERT INTO `health_model` VALUES (16, '饮水量', '每日饮水量直接影响新陈代谢效率和身体排毒功能，成人建议每日饮水1500-2000ml，运动后需额外补充', '/api/v1.0/self-health-api/file/getFile?fileName=1754393779064xt.png', '毫升(ml)', 'WATER', '1500,2000', NULL, 0, '2025-09-02 10:00:00');
INSERT INTO `health_model` VALUES (17, '腰围', '腰围是反映腹部脂肪堆积程度的简易指标，男性警戒线≥90cm，女性≥85cm，超标提示中心性肥胖风险', '/api/v1.0/self-health-api/file/getFile?fileName=1753760115590BMI.png', '厘米(cm)', 'WC', '70,85', NULL, 0, '2025-09-03 10:00:00');
INSERT INTO `health_model` VALUES (18, '运动时长', '每日/每周的运动总时长，世界卫生组织建议每周至少150分钟中等强度有氧运动', '/api/v1.0/self-health-api/file/getFile?fileName=1753597325751rate.png', '分钟(min)', 'EX', '30,60', NULL, 0, '2025-09-04 10:00:00');

-- ----------------------------
-- Table structure for health_news
-- ----------------------------
DROP TABLE IF EXISTS `health_news`;
CREATE TABLE `health_news`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '健康资讯主键ID，自增',
  `type_id` int NULL DEFAULT NULL COMMENT '资讯分类ID，外键，资讯分类通过后端枚举类进行管理',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资讯封面',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '内容',
  `summary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '摘要',
  `create_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '健康资讯表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of health_news
-- ----------------------------
INSERT INTO `health_news` VALUES (1, 2, '/api/v1.0/self-health-api/file/getFile?fileName=1753534656538Snipaste_2025-04-21_16-57-23.png', '早餐吃不对，全天易疲惫？营养专家推荐 3 类黄金搭配', '<p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" style=\"width: 50%;\"/></p><p><strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p>', '全谷物 + 优质蛋白是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 ', '2025-07-26 20:58:36');
INSERT INTO `health_news` VALUES (7, 1, '/api/v1.0/self-health-api/file/getFile?fileName=1754313964000Snipaste_2025-04-21_16-58-17.png', '有氧运动入门指南：从零开始的健康旅程', '<p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" style=\"width: 100%;\"/> <strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p>', '蔬菜 + 水果能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。', '2025-08-04 21:26:22');
INSERT INTO `health_news` VALUES (8, 1, '/api/v1.0/self-health-api/file/getFile?fileName=1754314012947Snipaste_2025-04-21_16-56-22.png', '每周150分钟：科学解读有氧运动时长标准', '<p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 <img src=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" style=\"width: 100%;\"/> <strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p>', '优质蛋白是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。', '2025-08-04 21:27:29');
