INSERT INTO `health_news` VALUES (11, 3, '/api/v1.0/self-health-api/file/getFile?fileName=1754314146011Snipaste_2025-04-21_16-58-30.png', '正念冥想入门：每天5分钟改善情绪', '<p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=1753534646517Snipaste_2025-04-21_16-57-23.png\" style=\"width: 100%;\"/> <strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p><p><br></p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。 </p><p><strong>蔬菜 + 水果</strong>能快速补充维生素。早餐加入菠菜、番茄等深色蔬菜，或搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。</p>', '搭配一小把蓝莓、草莓，可提供丰富的抗氧化物质，帮助清除代谢废物。上班族可提前准备蔬菜蛋卷，搭配便携水果，轻松满足需求。', '2025-08-04 21:29:21');
